// Public area cells, never device coordinates. One opt-in placement per post.
const FIT_TAGS=['Leggero','A strati','Impermeabile','Ombrello','Scarpe chiuse'];
function fitCell(lat,lon){return {lat:Math.round(lat*50),lon:((Math.round(lon*50)+9000)%18000+18000)%18000-9000}}
function fitCoordinates(b){return Number.isFinite(b.latitude)&&Number.isFinite(b.longitude)&&Math.abs(b.latitude)<=85&&Math.abs(b.longitude)<=180}
async function fitcheckApi(req,env,url){
 const user=await identity(req),now=Date.now(),path=url.pathname;
 if(req.method==='GET'&&path==='/api/fitcheck/feed'){
  if(!url.searchParams.has('latitude')||!url.searchParams.has('longitude'))fail(400,'Scegli una zona.');
  const input={latitude:Number(url.searchParams.get('latitude')),longitude:Number(url.searchParams.get('longitude'))};
  const radius=Number(url.searchParams.get('radius')||5),tag=clean(url.searchParams.get('tag'),30);
  if(!fitCoordinates(input)||![5,20].includes(radius)||(tag&&!FIT_TAGS.includes(tag)))fail(400,'Zona o filtro non validi.');
  const cell=fitCell(input.latitude,input.longitude),lat=cell.lat/50,lon=cell.lon/50,dy=radius/110.5,dx=Math.min(180,radius/(110.5*Math.cos(lat*Math.PI/180)));
  const args=[now,now,Math.floor((lat-dy)*50),Math.ceil((lat+dy)*50)];
  let longitude='';const west=lon-dx,east=lon+dx;
  if(west<-180){longitude='(f.lon>=? OR f.lon<=?)';args.push(Math.floor((west+360)*50),Math.ceil(east*50))}
  else if(east>180){longitude='(f.lon>=? OR f.lon<=?)';args.push(Math.floor(west*50),Math.ceil((east-360)*50))}
  else{longitude='f.lon BETWEEN ? AND ?';args.push(Math.floor(west*50),Math.ceil(east*50))}
  let extra='';if(tag){extra+=' AND f.tag=?';args.push(tag)}
  if(user){extra+=" AND NOT EXISTS(SELECT 1 FROM links b WHERE b.user=? AND b.target=p.author AND b.kind='block')";args.push(user)}
  const rows=(await q(env,`SELECT p.id,p.author,p.text,p.city,p.photo,p.video,p.created,COALESCE(u.name,'Redazione') name,f.lat,f.lon,f.tag,f.expires FROM fit_checks f JOIN posts p ON p.id=f.post LEFT JOIN profiles u ON u.id=p.author WHERE f.expires>? AND p.deleted=0 AND (p.expires IS NULL OR p.expires>?) AND f.lat BETWEEN ? AND ? AND ${longitude}${extra} ORDER BY p.created DESC,p.id DESC LIMIT 201`,...args).all()).results;
  const posts=rows.slice(0,200).map(p=>({...p,latitude:p.lat/50,longitude:p.lon/50,distance:pulseDistance({lat,lon},{lat:p.lat/50,lon:p.lon/50})})).filter(p=>p.distance<=radius).slice(0,100).map(({lat,lon,...p})=>p);
  return json({posts,limited:rows.length>200||posts.length===100,center:{latitude:lat,longitude:lon},radius,asOf:now,precision:'Zona approssimata scelta dall’autore. Celle di circa 2 km in latitudine, più strette verso i poli.'});
 }
 if(!user)fail(401,'Accedi per aggiungere il tuo Fit Check.');
 if(req.method==='GET'&&path==='/api/fitcheck/mine'){
  const rows=(await q(env,"SELECT p.id,p.text,p.city,p.photo,p.video,p.created,f.tag,f.lat,f.lon,f.expires FROM posts p LEFT JOIN fit_checks f ON f.post=p.id WHERE p.author=? AND p.deleted=0 AND p.created>? AND (p.expires IS NULL OR p.expires>?) AND (p.photo IS NOT NULL OR p.video IS NOT NULL) ORDER BY p.created DESC,p.id DESC LIMIT 30",user,now-86400000,now).all()).results;
  return json({posts:rows.map(({lat,lon,...p})=>({...p,latitude:lat===null?null:lat/50,longitude:lon===null?null:lon/50}))});
 }
 if(req.method!=='POST'||!['/api/fitcheck/place','/api/fitcheck/remove'].includes(path))fail(404,'Funzione non disponibile.');
 if(req.headers.get('origin')!==url.origin||!req.headers.get('content-type')?.includes('application/json'))fail(403,'Richiesta non autorizzata.');
 const raw=await req.text();if(raw.length>2000)fail(413,'Richiesta troppo estesa.');let b;try{b=JSON.parse(raw)}catch{fail(400,'Dati non validi.')}
 const id=clean(b?.post,50);if(!/^[a-f0-9-]{36}$/.test(id))fail(400,'Scegli un post.');
 const post=await q(env,'SELECT * FROM posts WHERE id=? AND author=?',id,user).first();if(!post)fail(404,'Puoi modificare solo un tuo post.');
 await quota(env,user,'fit-check-write',30);
 if(path.endsWith('/remove')){await q(env,'DELETE FROM fit_checks WHERE post=?',id).run();return json({ok:true})}
 if(post.deleted||post.created<=now-86400000||(post.expires&&post.expires<=now)||(!post.photo&&!post.video))fail(409,'Scegli una tua foto o un video pubblicato nelle ultime 24 ore.');
 if(!fitCoordinates(b)||b.consent!==true||!FIT_TAGS.includes(b.tag))fail(400,'Scegli la zona, un consiglio e conferma la pubblicazione.');
 const cell=fitCell(b.latitude,b.longitude),expires=Math.min(post.created+86400000,post.expires||Infinity);
 const known=ATLAS_CITIES.find(c=>c.name.toLocaleLowerCase()===post.city.trim().toLocaleLowerCase());
 if(known&&pulseDistance({lat:cell.lat/50,lon:cell.lon/50},{lat:known.latitude,lon:known.longitude})>35)fail(400,'La zona è lontana dalla città indicata nel post. Scegli un’area entro 35 km da '+known.name+'.');
 await q(env,'INSERT INTO fit_checks(post,lat,lon,tag,expires) VALUES(?,?,?,?,?) ON CONFLICT(post) DO UPDATE SET lat=excluded.lat,lon=excluded.lon,tag=excluded.tag,expires=excluded.expires',id,cell.lat,cell.lon,b.tag,expires).run();
 return json({ok:true,latitude:cell.lat/50,longitude:cell.lon/50,expires});
}

// Server-owned room lifetimes and editorial rewards. Client coordinates are
// declared browser location, not attested proof of presence or weather.
async function studioAssets(env,user){
 const row=await q(env,"SELECT COUNT(DISTINCT l.user) people FROM links l JOIN posts p ON p.id=l.target WHERE p.author=? AND p.deleted=0 AND (p.expires IS NULL OR p.expires>?) AND l.kind='like' AND l.user<>p.author AND NOT EXISTS(SELECT 1 FROM links b WHERE b.user=p.author AND b.target=l.user AND b.kind='block')",user,Date.now()).first();
 const earned=(await q(env,"SELECT item FROM inventory WHERE user=? AND item LIKE 'graphic_%'",user).all()).results.map(r=>r.item);
 return {people:row.people,earned,threshold:10,meaning:'Persone distinte che hanno apprezzato contenuti attivi. Non è una misura di viralità.'};
}
async function studioApi(req,env,url){
 const user=await identity(req),now=Date.now(),path=url.pathname;
 if(!user)fail(401,'Accedi con il tuo profilo per entrare.');
 if(req.method==='GET'&&path==='/api/studio/assets')return json(await studioAssets(env,user));
 if(req.method==='GET'&&path==='/api/studio/room'){
  const id=clean(url.searchParams.get('id'),70);const room=await q(env,'SELECT r.* FROM weather_rooms r JOIN weather_room_members m ON m.room=r.id WHERE r.id=? AND r.expires>? AND m.user=? AND m.expires>?',id,now,user,now).first();if(!room)fail(410,'Stanza o accesso scaduti. Verifica di nuovo la tua zona.');
  const messages=(await q(env,"SELECT m.id,m.user,m.text,m.created,COALESCE(p.name,'Redazione') name FROM weather_room_messages m LEFT JOIN profiles p ON p.id=m.user WHERE m.room=? AND m.deleted=0 AND NOT EXISTS(SELECT 1 FROM links b WHERE b.user=? AND b.target=m.user AND b.kind='block') ORDER BY m.created DESC,m.id DESC LIMIT 60",id,user).all()).results.reverse();return json({room,messages});
 }
 if(req.method!=='POST')fail(404,'Funzione non disponibile.');if(req.headers.get('origin')!==url.origin||!req.headers.get('content-type')?.includes('application/json'))fail(403,'Richiesta non autorizzata.');const raw=await req.text();if(raw.length>5000)fail(413,'Richiesta troppo estesa.');let b;try{b=JSON.parse(raw)}catch{fail(400,'Dati non validi.')}if(!await q(env,'SELECT id FROM profiles WHERE id=?',user).first())fail(400,'Scegli prima il nome della tua redazione nel Profilo.');
 if(path==='/api/studio/unlock'){
  await quota(env,user,'studio-unlock',10);const assets=await studioAssets(env,user);if(assets.people<assets.threshold)fail(409,'Servono apprezzamenti da 10 persone distinte sui tuoi contenuti.');await q(env,'INSERT OR IGNORE INTO inventory(user,item,created) VALUES(?,?,?)',user,'graphic_orbit',now).run();return json({ok:true,item:'graphic_orbit'});
 }
 if(path==='/api/studio/enter'){
  await quota(env,user,'storm-room-enter',6);
  if(!Number.isFinite(b.latitude)||!Number.isFinite(b.longitude)||Math.abs(b.latitude)>85||Math.abs(b.longitude)>180||!Number.isFinite(b.accuracy)||b.accuracy<0||b.accuracy>5000)fail(400,'Serve una posizione del dispositivo sufficientemente precisa.');
  const rounded={lat:Math.round(b.latitude*100)/100,lon:Math.round(b.longitude*100)/100};const city=ATLAS_CITIES.map(c=>({...c,km:pulseDistance(rounded,{lat:c.latitude,lon:c.longitude})})).sort((a,b)=>a.km-b.km)[0];if(!city||city.km>20)fail(400,'Le stanze sono inizialmente disponibili entro 20 km dalle città del catalogo.');
  const meteo=await socialWeather(rounded.lat,rounded.lon);const measured=Date.parse(String(meteo.time)+'Z')-Number(meteo.utc_offset_seconds)*1000;if(!Number.isFinite(measured)||Math.abs(now-measured)>5400000)fail(503,'Dati meteo non abbastanza recenti per aprire una stanza.');if(![95,96,99].includes(meteo.weather_code))return json({active:false,city:city.name,reason:'Il modello meteo non indica un temporale adesso. Nessuna stanza viene creata.',sourceTime:meteo.time});
  // Purge expired conversations when a room is entered. No precise GPS saved.
  await q(env,'DELETE FROM weather_room_messages WHERE room IN(SELECT id FROM weather_rooms WHERE expires<=?)',now).run();await q(env,'DELETE FROM weather_room_members WHERE expires<=? OR room IN(SELECT id FROM weather_rooms WHERE expires<=?)',now,now).run();await q(env,'DELETE FROM weather_rooms WHERE expires<=?',now).run();
  const id='storm-'+city.id+'-'+Math.floor(now/1800000),expires=(Math.floor(now/1800000)+1)*1800000;
  await q(env,'INSERT OR IGNORE INTO weather_rooms(id,city,created,expires,source_time) VALUES(?,?,?,?,?)',id,city.name,now,expires,String(meteo.time)).run();await q(env,'INSERT INTO weather_room_members(user,room,expires) VALUES(?,?,?) ON CONFLICT(user,room) DO UPDATE SET expires=excluded.expires',user,id,Math.min(expires,now+600000)).run();return json({active:true,id,city:city.name,expires,accessExpires:Math.min(expires,now+600000),sourceTime:meteo.time,source:'Open-Meteo · stima di modello, non allerta',presence:'Posizione dichiarata dal browser, non certificata'});
 }
 if(['/api/studio/message','/api/studio/delete-message','/api/studio/flag-message'].includes(path)){
  await quota(env,user,'storm-room-write',40);const id=clean(b.room,70);const member=await q(env,'SELECT m.user FROM weather_room_members m JOIN weather_rooms r ON r.id=m.room WHERE m.user=? AND m.room=? AND m.expires>? AND r.expires>?',user,id,now,now).first();if(!member)fail(410,'L’accesso alla stanza è scaduto. Verifica di nuovo la posizione.');
  if(path.endsWith('/message')){const text=clean(b.text,500),message=clean(b.id,50);if(!text||!/^[-a-f0-9]{36}$/.test(message))fail(400,'Scrivi un messaggio fino a 500 caratteri.');const exists=await q(env,'SELECT user,room FROM weather_room_messages WHERE id=?',message).first();if(exists&&(exists.user!==user||exists.room!==id))fail(409,'Identificativo già usato.');await q(env,'INSERT OR IGNORE INTO weather_room_messages(id,room,user,text,created,deleted) VALUES(?,?,?,?,?,0)',message,id,user,text,now).run();return json({ok:true})}
  const msg=await q(env,'SELECT id,user FROM weather_room_messages WHERE id=? AND room=? AND deleted=0',clean(b.id,50),id).first();if(!msg)fail(404,'Messaggio non disponibile.');
  if(path.endsWith('/delete-message')){if(msg.user!==user)fail(403,'Puoi eliminare solo i tuoi messaggi.');await q(env,'UPDATE weather_room_messages SET deleted=1,text=? WHERE id=?','',msg.id).run();return json({ok:true})}
  const reason=clean(b.reason,200);if(!reason)fail(400,'Indica il motivo.');await q(env,'INSERT OR REPLACE INTO weather_room_flags(user,message,reason,created) VALUES(?,?,?,?)',user,msg.id,reason,now).run();return json({ok:true});
 }
 fail(404,'Funzione non disponibile.');
}

// Nearby information and weekly community challenges. Never produces storm ETAs.
const pulseCityKey=s=>String(s||'').normalize('NFKC').trim().toLocaleLowerCase('it-IT');
function pulseWeek(now=Date.now()){const d=new Date(now);d.setUTCHours(0,0,0,0);d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10)}
function pulseDistance(a,b){const r=Math.PI/180,dl=(b.lat-a.lat)*r,dn=(b.lon-a.lon)*r,h=Math.sin(dl/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dn/2)**2;return 6371*2*Math.asin(Math.sqrt(Math.min(1,h)))}
function pulseOSM(elements){return elements.flatMap(e=>{const t=e.tags||{},lat=e.lat??e.center?.lat,lon=e.lon??e.center?.lon;if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180||!['node','way','relation'].includes(e.type)||!Number.isSafeInteger(e.id))return [];if(['private','no','permit','military'].includes(t.access)||['private','no'].includes(t.motor_vehicle)||t.disused==='yes')return [];const parking=t.amenity==='parking'&&(t.covered==='yes'||['underground','multi-storey','garage'].includes(t.parking));const building=['library','community_centre','townhall'].includes(t.amenity);if(!parking&&!building)return [];return [{id:'osm-'+e.type+'-'+e.id,name:clean(t.name,100)||(parking?'Parcheggio coperto':'Edificio pubblico'),lat,lon,type:parking?'car':'people',source:'OpenStreetMap',sourceURL:'https://www.openstreetmap.org/'+e.type+'/'+e.id,details:clean([t['addr:street'],t['addr:housenumber']].filter(Boolean).join(' '),160),openingHours:clean(t.opening_hours,150)||null,fee:t.fee==='yes'?'A pagamento':t.fee==='no'?'Gratuito indicato':'Costo da verificare',access:clean(t.access,40)||'unknown',availableSlots:null}];})}
async function pulseNearby(env,url,user){
 const latText=url.searchParams.get('lat'),lonText=url.searchParams.get('lon'),lat=Number(latText),lon=Number(lonText);if(!latText||!lonText||!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>85||Math.abs(lon)>180)fail(400,'Scegli una posizione valida tra 85° sud e 85° nord.');
 // Round before querying a third party. Never store the visitor's exact GPS position.
 const category=url.searchParams.get('category')==='people'?'people':'car';
 const center={lat:Math.round(lat*100)/100,lon:Math.round(lon*100)/100},cache=optionalPublicCache(),key=new Request(url.origin+'/api/pulse/osm-cell?lat='+center.lat+'&lon='+center.lon+'&category='+category);let osm=[],sourceError='',osmAt=null;
 try{const hit=await cache?.match(key);let payload;if(hit)payload=await hit.json();else{
  // Limit the whole application's upstream use; this is not a per-visitor allowance.
  const limit=await q(env,'INSERT INTO limits(key,count) VALUES(?,1) ON CONFLICT(key) DO UPDATE SET count=count+1 RETURNING count','nearby-osm:'+new Date().toISOString().slice(0,10)).first();if(limit.count>80)throw Error('Ricerca cartografica temporaneamente al limite. Restano i luoghi della community.');
  const filter=category==='people'?'[amenity=library]':'[amenity=parking][covered=yes]';
  const query=`[out:json][timeout:15];nwr${filter}(around:6000,${center.lat},${center.lon});out center 40;`;
  const r=await fetch('https://overpass.private.coffee/api/interpreter',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','User-Agent':'MeteoSocial/1.1 (+https://scudo-meteo-community.walkerthehate.chatgpt.site)'},body:new URLSearchParams({data:query}),signal:AbortSignal.timeout(27000)});if(!r.ok)throw Error('Cartografia dei luoghi temporaneamente non disponibile.');
  const raw=await r.text();if(raw.length>300000)throw Error('Risposta cartografica troppo estesa.');const d=JSON.parse(raw);if(!Array.isArray(d.elements)||d.remark)throw Error('Ricerca cartografica incompleta. Riprova più tardi.');payload={places:pulseOSM(d.elements).slice(0,100),updated:d.osm3s?.timestamp_osm_base||Date.now()};if(cache)await cache.put(key,new Response(JSON.stringify(payload),{headers:{'Cache-Control':'public,max-age=21600','Content-Type':'application/json'}}));
 }osm=payload.places;osmAt=payload.updated}catch(e){sourceError=['TimeoutError','AbortError','TypeError','SyntaxError'].includes(e.name)?'La fonte cartografica non ha risposto in tempo. Puoi riprovare o usare Google Maps.':e.message||'Cartografia non disponibile.'}
 const lonSpan=.07/Math.max(.05,Math.cos(center.lat*Math.PI/180)),args=[center.lat-.07,center.lat+.07,center.lon,lonSpan,center.lon,360-lonSpan];const clause=user?" AND NOT EXISTS(SELECT 1 FROM links b WHERE b.user=? AND b.target=s.author AND b.kind='block')":'';if(user)args.push(user);
 const rows=(await q(env,'SELECT s.* FROM shelters s WHERE s.deleted=0 AND CAST(s.lat AS REAL) BETWEEN ? AND ? AND (ABS(CAST(s.lon AS REAL)-?)<=? OR ABS(CAST(s.lon AS REAL)-?)>=?)'+clause+' ORDER BY s.created DESC LIMIT 201',...args).all()).results;
 const community=rows.slice(0,200).map(s=>({id:s.id,name:s.name,lat:Number(s.lat),lon:Number(s.lon),type:'unknown',source:'Community',sourceURL:null,details:s.details,city:s.city,created:s.created,author:s.author,openingHours:null,fee:'Da verificare',availableSlots:null}));
 const places=[...osm,...community].filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon)&&pulseDistance(center,p)<=6.8);
 return json({places,sourceError,osmAt,updated:Date.now(),radiusKm:5,truncated:rows.length>200,originPrecision:'rounded_0.01_degrees',availability:'unknown'});
}
async function pulseApi(req,env,url){
 const user=await identity(req),now=Date.now(),week=pulseWeek(now),path=url.pathname;
 if(path==='/api/pulse/nearby'&&req.method==='GET')return pulseNearby(env,url,user);
 if(path==='/api/pulse/trends'&&req.method==='GET'){
  const args=[now-86400000,now,now],blocked=user?" AND NOT EXISTS(SELECT 1 FROM links b WHERE b.user=? AND b.target=p.author AND b.kind='block')":'';if(user)args.push(user);
  const where='p.deleted=0 AND p.created>=? AND p.created<=? AND (p.expires IS NULL OR p.expires>?)'+blocked;
  const themes=(await q(env,'SELECT p.kind,COUNT(*) posts,COUNT(DISTINCT p.author) people,MAX(p.created) latest FROM posts p WHERE '+where+' GROUP BY p.kind ORDER BY people DESC,posts DESC,p.kind LIMIT 8',...args).all()).results;
  const cities=(await q(env,'SELECT MIN(p.city) city,COUNT(*) posts,COUNT(DISTINCT p.author) people,MAX(p.created) latest FROM posts p WHERE '+where+' GROUP BY lower(trim(p.city)) ORDER BY people DESC,posts DESC,city LIMIT 8',...args).all()).results;
  return json({themes,cities,windowHours:24,updated:now,meaning:'Attività della community, non intensità meteo o tendenze esterne.'});
 }
 if(path==='/api/pulse/challenges'&&req.method==='GET'){
  const start=Date.parse(week+'T00:00:00Z'),end=start+7*86400000;
  const rows=(await q(env,`SELECT e.city,COUNT(*) points,COUNT(DISTINCT e.user) contributors FROM city_challenge_entries e JOIN posts p ON p.id=e.post WHERE e.week=? AND p.deleted=0 AND p.created>=? AND p.created<? AND (p.expires IS NULL OR p.expires>?) GROUP BY e.city ORDER BY points DESC,e.city`,week,start,end,now).all()).results;
  const members=(await q(env,'SELECT city,COUNT(*) members FROM city_challenge_members WHERE week=? GROUP BY city',week).all()).results;
  const mine=user?await q(env,'SELECT city FROM city_challenge_members WHERE user=? AND week=?',user,week).first():null;
  const entries=user?(await q(env,'SELECT e.post,e.day,e.city FROM city_challenge_entries e JOIN posts p ON p.id=e.post WHERE e.user=? AND e.week=? AND p.deleted=0',user,week).all()).results:[];
  const board=ATLAS_CITIES.map(c=>({id:c.id,name:c.name,points:rows.find(r=>r.city===c.id)?.points||0,contributors:rows.find(r=>r.city===c.id)?.contributors||0,members:members.find(r=>r.city===c.id)?.members||0})).filter(c=>c.points||c.members).sort((a,b)=>b.points-a.points||a.name.localeCompare(b.name));
  return json({week,ends:end,board,mine:mine?.city||null,entries,updated:now});
 }
 if(req.method!=='POST')fail(404,'Funzione non disponibile.');if(!user)fail(401,'Accedi per partecipare alla sfida.');if(req.headers.get('origin')!==url.origin||!req.headers.get('content-type')?.includes('application/json'))fail(403,'Richiesta non autorizzata.');const raw=await req.text();if(raw.length>4000)fail(413,'Richiesta troppo grande.');let b;try{b=JSON.parse(raw)}catch{fail(400,'Dati non validi.')}await quota(env,user,'city-challenge',25);if(!await q(env,'SELECT id FROM profiles WHERE id=?',user).first())fail(400,'Scegli prima il tuo nome nel Profilo.');
 if(path==='/api/pulse/join'){
  const city=ATLAS_CITIES.find(c=>c.id===b.city);if(!city)fail(400,'Scegli una città dall’elenco.');const entry=await q(env,'SELECT city FROM city_challenge_entries WHERE user=? AND week=? LIMIT 1',user,week).first();if(entry&&entry.city!==city.id)fail(409,'Hai già contribuito per un’altra città. Puoi cambiare dalla prossima settimana.');
  const joined=await q(env,'INSERT INTO city_challenge_members(user,week,city) VALUES(?,?,?) ON CONFLICT(user,week) DO UPDATE SET city=excluded.city WHERE NOT EXISTS(SELECT 1 FROM city_challenge_entries e WHERE e.user=excluded.user AND e.week=excluded.week AND e.city<>excluded.city)',user,week,city.id).run();if(!joined.meta.changes)fail(409,'La squadra resta quella del primo contributo della settimana.');return json({ok:true,city:city.id});
 }
 if(path==='/api/pulse/entry'){
  const p=await q(env,'SELECT * FROM posts WHERE id=? AND author=? AND deleted=0',clean(b.post,50),user).first();if(!p)fail(404,'Scegli una tua foto o un tuo video.');const start=Date.parse(week+'T00:00:00Z');if(p.created<start||p.created>now||p.expires||!['Cielo sereno','Osservazione'].includes(p.kind)||(!p.photo&&!p.video))fail(400,'La sfida accetta foto e video del cielo di questa settimana, come Osservazione o Cielo sereno.');
  const member=await q(env,'SELECT city FROM city_challenge_members WHERE user=? AND week=?',user,week).first(),city=ATLAS_CITIES.find(c=>c.id===member?.city);if(!city)fail(400,'Scegli prima una squadra nella pagina Sfide.');if(pulseCityKey(p.city)!==pulseCityKey(city.name))fail(400,'La località del post deve corrispondere alla città scelta.');
  const previous=await q(env,'SELECT post FROM city_challenge_entries WHERE post=?',p.id).first();if(previous)return json({ok:true,already:true});const day=new Date(p.created).toISOString().slice(0,10);
  const added=await q(env,'INSERT OR IGNORE INTO city_challenge_entries(post,user,week,day,city) SELECT ?,?,?,?,? WHERE EXISTS(SELECT 1 FROM city_challenge_members WHERE user=? AND week=? AND city=?)',p.id,user,week,day,city.id,user,week,city.id).run();if(!added.meta.changes)fail(409,'Hai già un contributo per quel giorno: massimo uno al giorno, sette a settimana.');return json({ok:true});
 }
 fail(404,'Funzione non disponibile.');
}

