  const posts=rows.slice(0,20),last=posts.at(-1),links=user?(await q(env,'SELECT kind,target FROM links WHERE user=?',user).all()).results:[];
  return json({posts,links,cursor:rows.length>20?last.created+'_'+last.id:null});
