  const id=path.split('/').pop(),p=await q(env,'SELECT video,author FROM posts WHERE id=? AND deleted=0 AND (expires IS NULL OR expires>?)',id,now).first();if(!p?.video)fail(404,'Video non disponibile.');if(user&&await q(env,"SELECT user FROM links WHERE user=? AND target=? AND kind='block'",user,p.author).first())fail(404,'Contenuto nascosto.');const o=await env.BUCKET.get(p.video);if(!o)fail(404,'Video non disponibile.');const bytes=new Uint8Array(await o.arrayBuffer()),headers={'Content-Type':o.httpMetadata.contentType,'X-Content-Type-Options':'nosniff','Cache-Control':'private,no-store','Accept-Ranges':'bytes'};const range=req.headers.get('range');if(range){const m=/^bytes=(\d*)-(\d*)$/.exec(range);if(!m||(!m[1]&&!m[2]))return new Response(null,{status:416,headers:{'Content-Range':'bytes */'+bytes.length}});const start=m[1]?Number(m[1]):Math.max(0,bytes.length-Number(m[2])),end=m[1]&&m[2]?Math.min(Number(m[2]),bytes.length-1):bytes.length-1;if(start>end||start>=bytes.length)return new Response(null,{status:416,headers:{'Content-Range':'bytes */'+bytes.length}});return new Response(req.method==='HEAD'?null:bytes.slice(start,end+1),{status:206,headers:{...headers,'Content-Length':String(end-start+1),'Content-Range':`bytes ${start}-${end}/${bytes.length}`}})}return new Response(req.method==='HEAD'?null:bytes,{headers:{...headers,'Content-Length':String(bytes.length)}})
