 if(!file||typeof file.arrayBuffer!=='function'||file.size>8000000||file.size<16||!['video/mp4','video/webm'].includes(file.type))fail(400,'Scegli MP4 o WebM fino a 8 MB.');const bytes=new Uint8Array(await file.arrayBuffer());const valid=file.type==='video/mp4'?new TextDecoder().decode(bytes.slice(4,8))==='ftyp':[26,69,223,163].every((b,i)=>bytes[i]===b);if(!valid)fail(400,'Il file non è un video supportato.');const key='clips/'+id;
