// Unique (event,actor) prevents duplicate notices even with concurrent readers.
async function recordEventChange(env,g,reader){
 await q(env,`INSERT OR IGNORE INTO event_notices(id,actor,event,created) SELECT lower(hex(randomblob(16))),m.actor,?,? FROM event_members m WHERE m."group"=? AND NOT EXISTS(SELECT 1 FROM moderation_bans b WHERE b.key='actor:'||m.actor)`,g.id,Date.now(),g.id).run();
 if(reader)await q(env,'UPDATE event_notices SET seen=1 WHERE event=? AND actor=?',g.id,reader).run();
}
async function deliverEventNotices(env,event,origin){
 const pending=(await q(env,'SELECT id,actor FROM event_notices WHERE event=? AND seen=0 AND pushed=0 LIMIT 30',event).all()).results;
 for(let start=0;start<pending.length;start+=5)await Promise.all(pending.slice(start,start+5).map(n=>sendSchoolPush(env,n.actor,n.id,origin,'event')));
}

// Public-data cache is an optimization: restricted runtimes must still fetch the source.
function optionalPublicCache(){
 const open=async()=>globalThis.caches?.open?await globalThis.caches.open('meteosocial-public-v1'):globalThis.caches?.default;
 return {
  async match(key){try{return await (await open())?.match(key)}catch{return undefined}},
  async put(key,response){try{await (await open())?.put(key,response)}catch{/* Source response remains valid without caching. */}}
 };
}
